  {"type":"function","function":{"name":"github-mcp-server_list_issue_fields","description":"List issue fields for a repository or organization. Returns field definitions including name, type (text, number, date, single_select), and for single_select fields the list of valid option names. When repo is omitted, returns org-level fields directly.","parameters":{"type":"object","properties":{"owner":{"type":"string","description":"The account owner of the repository or organization. The name is not case sensitive.","x-mcp-header":"owner"},"repo":{"type":"string","description":"The name of the repository. When provided, returns fields for this specific repository (inherited from its organization). When omitted, returns org-level fields directly.","x-mcp-header":"repo"}},"required":["owner"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_issue_types","description":"List supported issue types for a repository or its owner organization. When repo is omitted, returns org-level issue types directly.","parameters":{"type":"object","properties":{"owner":{"type":"string","description":"The account owner of the repository or organization.","x-mcp-header":"owner"},"repo":{"type":"string","description":"The name of the repository. When provided, returns issue types for this specific repository. When omitted, returns org-level issue types directly.","x-mcp-header":"repo"}},"required":["owner"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_issues","description":"List issues in a GitHub repository. For pagination, use the 'endCursor' from the previous response's 'pageInfo' in the 'after' parameter.","parameters":{"type":"object","properties":{"after":{"type":"string","description":"Cursor for pagination. Use the cursor from the previous response."},"direction":{"type":"string","description":"Order direction. If provided, the 'orderBy' also needs to be provided.","enum":["ASC","DESC"]},"field_filters":{"type":"array","items":{"type":"object","properties":{"field_name":{"type":"string","description":"Name of the custom field (e.g. \"Priority\"). Case-insensitive."},"value":{"type":"string","description":"Value to filter on. For single-select fields, the option name (e.g. \"P1\"). For dates, YYYY-MM-DD. For numbers, the numeric value as a string. For text, the text value."}},"required":["field_name","value"]},"description":"Filter by custom issue field values. Each entry takes a field_name and a value; the server looks up the field and coerces the value to its type (single-select option name, text, number, or YYYY-MM-DD date)."},"fields":{"type":"array","items":{"type":"string","enum":["number","title","body","state","user","labels","assignees","comments","created_at","updated_at","field_values"]},"description":"Subset of fields to return for each issue. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' and 'field_values' in particular drops the largest per-result data."},"labels":{"type":"array","items":{"type":"string"},"description":"Filter by labels"},"orderBy":{"type":"string","description":"Order issues by field. If provided, the 'direction' also needs to be provided.","enum":["CREATED_AT","UPDATED_AT","COMMENTS"]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"},"since":{"type":"string","description":"Filter by date (ISO 8601 timestamp)"},"state":{"type":"string","description":"Filter by state, by default both open and closed issues are returned when not provided","enum":["OPEN","CLOSED"]}},"required":["owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_pull_requests","description":"List pull requests in a GitHub repository. If the user specifies an author, then DO NOT use this tool and use the search_pull_requests tool instead.","parameters":{"type":"object","properties":{"base":{"type":"string","description":"Filter by base branch"},"direction":{"type":"string","description":"Sort direction","enum":["asc","desc"]},"fields":{"type":"array","items":{"type":"string","enum":["number","title","body","state","draft","merged","mergeable_state","html_url","user","labels","assignees","requested_reviewers","merged_by","head","base","additions","deletions","changed_files","commits","comments","created_at","updated_at","closed_at","merged_at","milestone"]},"description":"Subset of fields to return for each pull request. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' in particular drops the largest per-result data."},"head":{"type":"string","description":"Filter by head user/org and branch"},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"},"sort":{"type":"string","description":"Sort by","enum":["created","updated","popularity","long-running"]},"state":{"type":"string","description":"Filter by state","enum":["open","closed","all"]}},"required":["owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_releases","description":"List releases in a GitHub repository","parameters":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"string","enum":["id","tag_name","name","body","html_url","published_at","prerelease","draft","author"]},"description":"Subset of fields to return for each release. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body' in particular drops the largest per-release data."},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_repository_collaborators","description":"List collaborators of a GitHub repository. Results are paginated; the response includes `nextPage`, `prevPage`, `firstPage`, and `lastPage` fields. To get the next page, use the `nextPage` value as the `page` parameter.","parameters":{"type":"object","properties":{"affiliation":{"type":"string","description":"Filter by affiliation. Can be one of: 'outside' (outside collaborators), 'direct' (all with permissions regardless of org membership), 'all' (all collaborators). Default: 'all'","enum":["outside","direct","all"]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (default 1, min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (default 30, min 1, max 100)","minimum":1,"maximum":100},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_list_tags","description":"List git tags in a GitHub repository","parameters":{"type":"object","properties":{"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_merge_pull_request","description":"Merge a pull request in a GitHub repository.","parameters":{"type":"object","properties":{"commit_message":{"type":"string","description":"Extra detail for merge commit"},"commit_title":{"type":"string","description":"Title for merge commit"},"expectedHeadSha":{"type":"string","description":"The expected SHA of the pull request's HEAD ref"},"merge_method":{"type":"string","description":"Merge method","enum":["merge","squash","rebase"]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"pullNumber":{"type":"number","description":"Pull request number"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_pull_request_read","description":"Get information on a specific pull request in GitHub repository.","parameters":{"type":"object","properties":{"after":{"type":"string","description":"Cursor for pagination, used only by the get_review_comments method. Pass the endCursor from the previous page's PageInfo to fetch the next page."},"method":{"type":"string","description":"Action to specify what pull request data needs to be retrieved from GitHub. \nPossible options: \n 1. get - Get details of a specific pull request.\n 2. get_diff - Get the diff of a pull request.\n 3. get_status - Get combined commit status of a head commit in a pull request.\n 4. get_files - Get the list of files changed in a pull request. Use with pagination parameters to control the number of results returned.\n 5. get_commits - Get the list of commits on a pull request. Use with pagination parameters to control the number of results returned.\n 6. get_review_comments - Get review threads on a pull request. Each thread contains logically grouped review comments made on the same code location during pull request reviews. Returns thread metadata and comments with nullable current and original line-range coordinates (line, start_line, original_line, original_start_line). Current coordinates are omitted when unavailable, such as for outdated comments. Use cursor-based pagination (perPage, after) to control results.\n 7. get_reviews - Get the reviews on a pull request. When asked for review comments, use get_review_comments method. Use with pagination parameters to control the number of results returned.\n 8. get_comments - Get comments on a pull request. Use this if user doesn't specifically want review comments. Use with pagination parameters to control the number of results returned.\n 9. get_check_runs - Get check runs for the head commit of a pull request. Check runs are the individual CI/CD jobs and checks that run on the PR.\n","enum":["get","get_diff","get_status","get_files","get_commits","get_review_comments","get_reviews","get_comments","get_check_runs"]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"pullNumber":{"type":"number","description":"Pull request number"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["method","owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_pull_request_review_write","description":"Create and/or submit, delete review of a pull request.\n\nAvailable methods:\n- create: Create a new review of a pull request. If \"event\" parameter is provided, the review is submitted. If \"event\" is omitted, a pending review is created.\n- submit_pending: Submit an existing pending review of a pull request. This requires that a pending review exists for the current user on the specified pull request. The \"body\" and \"event\" parameters are used when submitting the review.\n- delete_pending: Delete an existing pending review of a pull request. This requires that a pending review exists for the current user on the specified pull request.\n- resolve_thread: Resolve a review thread. Requires only \"threadId\" parameter with the thread's node ID (e.g., PRRT_kwDOxxx). The owner, repo, and pullNumber parameters are not used for this method. Resolving an already-resolved thread is a no-op.\n- unresolve_thread: Unresolve a previously resolved review thread. Requires only \"threadId\" parameter. The owner, repo, and pullNumber parameters are not used for this method. Unresolving an already-unresolved thread is a no-op.\n","parameters":{"type":"object","properties":{"body":{"type":"string","description":"Review comment text"},"commitID":{"type":"string","description":"SHA of commit to review"},"event":{"type":"string","description":"Review action to perform.","enum":["APPROVE","REQUEST_CHANGES","COMMENT"]},"method":{"type":"string","description":"The write operation to perform on pull request review.","enum":["create","submit_pending","delete_pending","resolve_thread","unresolve_thread"]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"pullNumber":{"type":"number","description":"Pull request number"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"},"threadId":{"type":"string","description":"The node ID of the review thread (e.g., PRRT_kwDOxxx). Required for resolve_thread and unresolve_thread methods. Get thread IDs from pull_request_read with method get_review_comments."}},"required":["method","owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_push_files","description":"Push multiple files to a GitHub repository in a single commit","parameters":{"type":"object","properties":{"branch":{"type":"string","description":"Branch to push to"},"files":{"type":"array","items":{"type":"object","properties":{"content":{"type":"string","description":"file content"},"path":{"type":"string","description":"path to the file"}},"required":["path","content"],"additionalProperties":false},"description":"Array of file objects to push, each object with path (string) and content (string)"},"message":{"type":"string","description":"Commit message"},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo","branch","files","message"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_request_copilot_review","description":"Request a GitHub Copilot code review for a pull request. Use this for automated feedback on pull requests, usually before requesting a human reviewer.","parameters":{"type":"object","properties":{"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"pullNumber":{"type":"number","description":"Pull request number"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_run_secret_scanning","description":"Scan files, content, or recent changes for secrets such as API keys, passwords, tokens, and credentials.\n\nThis tool is intended for targeted scans of specific files, snippets, or diffs provided directly as content. The files parameter accepts either a single string or an array of strings containing raw file contents or diff hunks, and returns detected secrets with their locations and related secret scanning metadata. Content must not be empty. For full repository scanning, other mechanisms are available.\n\nCaveats:\n\n- Only files within the codebase should be scanned. Files outside of the codebase should not be sent.\n- Files listed in .gitignore should be skipped.","parameters":{"type":"object","properties":{"files":{"description":"A single string or an array of strings containing file contents, snippets, or diff hunks to scan for secrets. These must be raw contents, not repository file paths.","anyOf":[{"type":"string","minLength":1},{"type":"array","items":{"type":"string"},"minItems":1,"maxItems":100}]},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["files","owner","repo"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_code","description":"Fast and precise code search across ALL GitHub repositories using GitHub's native search engine. Best for finding exact symbols, functions, classes, or specific code patterns.","parameters":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"string","enum":["name","path","sha","repository","text_matches"]},"description":"Subset of fields to return for each code search result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'repository' and 'text_matches' in particular drops the largest per-result data."},"order":{"type":"string","description":"Sort order for results","enum":["asc","desc"]},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"Search query (GitHub code search REST). Implicit AND between terms; supports `OR`, `NOT`, and `\"quoted phrase\"` for exact match. Qualifiers: `repo:owner/repo`, `org:`, `user:`, `language:`, `path:dir` (prefix match), `filename:exact.ext`, `extension:`, `in:file`, `in:path`, `size:`, `is:archived`, `is:fork`. Max 256 chars. Examples: `WithContext language:go org:github`; `\"package main\" repo:o/r`; `func extension:go path:cmd repo:o/r`; `NOT TODO language:go repo:o/r`."},"sort":{"type":"string","description":"Sort field ('indexed' only)"}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_commits","description":"Search for commits across GitHub repositories using GitHub's commit search syntax. Useful for finding specific changes, authors, or messages across one or many repositories. Searches the default branch only.","parameters":{"type":"object","properties":{"order":{"type":"string","description":"Sort order","enum":["asc","desc"]},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"Commit search query (GitHub commit search REST). Searches commit messages on the default branch only. Scope the search with `repo:owner/repo`, `org:`, or `user:` (queries without a scope qualifier match across all of GitHub and are usually not what you want). Other qualifiers: `author:`, `committer:`, `author-name:`, `committer-name:`, `author-email:`, `committer-email:`, `author-date:`, `committer-date:` (supports `>`, `<`, `>=`, `<=`, and `YYYY-MM-DD..YYYY-MM-DD` ranges), `merge:true|false`, `hash:`, `tree:`, `parent:`, `is:public`. Examples: `repo:owner/repo fix panic`; `org:github author:defunkt committer-date:>=2024-01-01`; `\"refactor cache\" repo:o/r`; `hash:abc1234 repo:o/r`."},"sort":{"type":"string","description":"Sort by author or committer date (defaults to best match)","enum":["author-date","committer-date"]}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_issues","description":"Search issues using natural-language semantic matching. Best for conceptual or paraphrased queries (e.g. \"login fails after password reset\"). Already scoped to is:issue.","parameters":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"string","enum":["number","title","body","state","state_reason","draft","locked","html_url","user","author_association","labels","assignee","assignees","milestone","comments","reactions","created_at","updated_at","closed_at","closed_by","type","repository_url","pull_request","field_values"]},"description":"Subset of fields to return for each issue result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data."},"order":{"type":"string","description":"Sort order","enum":["asc","desc"]},"owner":{"type":"string","description":"Optional repository owner. If provided with repo, only issues for this repository are listed.","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"The search query, as natural language. When the user gives alternative wordings, include them as plain words rather than joining them with OR."},"repo":{"type":"string","description":"Optional repository name. If provided with owner, only issues for this repository are listed.","x-mcp-header":"repo"},"sort":{"type":"string","description":"Sort field by number of matches of categories, defaults to best match","enum":["comments","reactions","reactions-+1","reactions--1","reactions-smile","reactions-thinking_face","reactions-heart","reactions-tada","interactions","created","updated"]}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_pull_requests","description":"Search for pull requests in GitHub repositories using issues search syntax already scoped to is:pr","parameters":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"string","enum":["number","title","body","state","state_reason","draft","locked","html_url","user","author_association","labels","assignee","assignees","milestone","comments","reactions","created_at","updated_at","closed_at","closed_by","pull_request","repository_url"]},"description":"Subset of fields to return for each pull request result. If omitted, all fields are returned. Use this to reduce response size when you only need specific fields; omitting 'body', 'reactions', and 'labels' in particular drops the largest per-result data."},"order":{"type":"string","description":"Sort order","enum":["asc","desc"]},"owner":{"type":"string","description":"Optional repository owner. If provided with repo, only pull requests for this repository are listed.","x-mcp-header":"owner"},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"Search query using GitHub pull request search syntax"},"repo":{"type":"string","description":"Optional repository name. If provided with owner, only pull requests for this repository are listed.","x-mcp-header":"repo"},"sort":{"type":"string","description":"Sort field by number of matches of categories, defaults to best match","enum":["comments","reactions","reactions-+1","reactions--1","reactions-smile","reactions-thinking_face","reactions-heart","reactions-tada","interactions","created","updated"]}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_repositories","description":"Find GitHub repositories by name, description, readme, topics, or other metadata. Perfect for discovering projects, finding examples, or locating specific repositories across GitHub.","parameters":{"type":"object","properties":{"minimal_output":{"type":"boolean","description":"Return minimal repository information (default: true). When false, modern clients receive additional curated repository details, not the complete GitHub API object. Legacy clients retain full GitHub API repository objects.","default":true},"order":{"type":"string","description":"Sort order","enum":["asc","desc"]},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"Repository search query. Examples: 'machine learning in:name stars:>1000 language:python', 'topic:react', 'user:facebook'. Supports advanced search syntax for precise filtering."},"sort":{"type":"string","description":"Sort repositories by field, defaults to best match","enum":["stars","forks","help-wanted-issues","updated"]}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_search_users","description":"Find GitHub users by username, real name, or other profile information. Useful for locating developers, contributors, or team members.","parameters":{"type":"object","properties":{"order":{"type":"string","description":"Sort order","enum":["asc","desc"]},"page":{"type":"number","description":"Page number for pagination (min 1)","minimum":1},"perPage":{"type":"number","description":"Results per page for pagination (min 1, max 100)","minimum":1,"maximum":100},"query":{"type":"string","description":"User search query. Examples: 'john smith', 'location:seattle', 'followers:>100'. Search is automatically scoped to type:user."},"sort":{"type":"string","description":"Sort users by number of followers or repositories, or when the person joined GitHub.","enum":["followers","repositories","joined"]}},"required":["query"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_sub_issue_write","description":"Add a sub-issue to a parent issue in a GitHub repository.","parameters":{"type":"object","properties":{"after_id":{"type":"number","description":"The ID of the sub-issue to be prioritized after (either after_id OR before_id should be specified)"},"before_id":{"type":"number","description":"The ID of the sub-issue to be prioritized before (either after_id OR before_id should be specified)"},"issue_number":{"type":"number","description":"The number of the parent issue"},"method":{"type":"string","description":"The action to perform on a single sub-issue\nOptions are:\n- 'add' - add a sub-issue to a parent issue in a GitHub repository.\n- 'remove' - remove a sub-issue from a parent issue in a GitHub repository.\n- 'reprioritize' - change the order of sub-issues within a parent issue in a GitHub repository. Use either 'after_id' or 'before_id' to specify the new position.\nWrites issue hierarchy. To move a sub-issue to a new parent, use `add` with `replace_parent=true`; there is no writable parent field.\n"},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"replace_parent":{"type":"boolean","description":"When true, replaces the sub-issue's current parent issue. Use with 'add' method only."},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"},"sub_issue_id":{"type":"number","description":"The ID of the sub-issue to add. ID is not the same as issue number"}},"required":["method","owner","repo","issue_number","sub_issue_id"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_ui_get","description":"Fetch UI data for MCP Apps (labels, assignees, milestones, issue types, branches, issue fields, reviewers).","parameters":{"type":"object","properties":{"method":{"type":"string","description":"The type of data to fetch","enum":["labels","assignees","milestones","issue_types","branches","issue_fields","reviewers"]},"owner":{"type":"string","description":"Repository owner (required for all methods)","x-mcp-header":"owner"},"repo":{"type":"string","description":"Repository name (required for labels, assignees, milestones, branches, issue fields, reviewers)","x-mcp-header":"repo"}},"required":["method","owner"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_update_issue_comment","description":"Update the body of an existing issue or pull request conversation comment. This tool cannot update pull request review comments.","parameters":{"type":"object","properties":{"body":{"type":"string","description":"New comment content","minLength":1},"comment_id":{"type":"integer","description":"The numeric ID of the issue or pull request conversation comment to update. Do not use a pull request review comment ID.","minimum":1},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo","comment_id","body"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_update_pull_request","description":"Update an existing pull request in a GitHub repository.","parameters":{"type":"object","properties":{"base":{"type":"string","description":"New base branch name"},"body":{"type":"string","description":"New description"},"draft":{"type":"boolean","description":"Mark pull request as draft (true) or ready for review (false)"},"maintainer_can_modify":{"type":"boolean","description":"Allow maintainer edits"},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"pullNumber":{"type":"number","description":"Pull request number to update"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"},"reviewers":{"type":"array","items":{"type":"string"},"description":"GitHub usernames or ORG/team-slug team reviewers to request reviews from"},"state":{"type":"string","description":"New state","enum":["open","closed"]},"title":{"type":"string","description":"New title"}},"required":["owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"github-mcp-server_update_pull_request_branch","description":"Update the branch of a pull request with the latest changes from the base branch.","parameters":{"type":"object","properties":{"expectedHeadSha":{"type":"string","description":"The expected SHA of the pull request's HEAD ref"},"owner":{"type":"string","description":"Repository owner","x-mcp-header":"owner"},"pullNumber":{"type":"number","description":"Pull request number"},"repo":{"type":"string","description":"Repository name","x-mcp-header":"repo"}},"required":["owner","repo","pullNumber"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"glob","description":"- Fast file pattern matching tool that works with any codebase size\n- Supports glob patterns like \"**/*.js\" or \"src/**/*.ts\"\n- Returns matching file paths\n- Use this tool when you need to find files by name patterns\n- When you are doing an open-ended search that may require multiple rounds of globbing and grepping, use the Task tool instead\n- You have the capability to call multiple tools in a single response. It is always better to speculatively perform multiple searches as a batch that are potentially useful.\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"pattern":{"type":"string","description":"The glob pattern to match files against"},"path":{"type":"string","description":"The directory to search in. If not specified, the current working directory will be used. IMPORTANT: Omit this field to use the default directory. DO NOT enter \"undefined\" or \"null\" - simply omit it for the default behavior. Must be a valid directory path if provided."}},"required":["pattern"]}}},
  {"type":"function","function":{"name":"grep","description":"- Fast content search tool that works with any codebase size\n- Searches file contents using regular expressions\n- Supports full regex syntax (eg. \"log.*Error\", \"function\\s+\\w+\", etc.)\n- Filter files by pattern with the include parameter (eg. \"*.js\", \"*.{ts,tsx}\")\n- Returns file paths and line numbers with matching lines\n- Use this tool when you need to find files containing specific patterns\n- If you need to identify/count the number of matches within files, use the Bash tool with `rg` (ripgrep) directly. Do NOT use `grep`.\n- When you are doing an open-ended search that may require multiple rounds of globbing and grepping, use the Task tool instead\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"pattern":{"type":"string","description":"The regex pattern to search for in file contents"},"path":{"type":"string","description":"The directory to search in. Defaults to the current working directory."},"include":{"type":"string","description":"File pattern to include in the search (e.g. \"*.js\", \"*.{ts,tsx}\")"}},"required":["pattern"]}}},
  {"type":"function","function":{"name":"list_mcp_resource_templates","description":"Lists resource templates provided by connected MCP servers. Resource templates are parameterized resources that can be read after filling in their URI template.","parameters":{"type":"object","properties":{"server":{"type":"string","description":"Optional MCP server name. When omitted, lists resource templates from every connected server."}},"additionalProperties":false}}},
  {"type":"function","function":{"name":"list_mcp_resources","description":"Lists resources provided by connected MCP servers. Resources provide context such as files, database schemas, or application-specific information.","parameters":{"type":"object","properties":{"server":{"type":"string","description":"Optional MCP server name. When omitted, lists resources from every connected server."}},"additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_click","description":"Perform click on a web page","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"doubleClick":{"description":"Whether to perform a double click instead of a single click","type":"boolean"},"button":{"description":"Button to click, defaults to left","type":"string","enum":["left","right","middle"]},"modifiers":{"description":"Modifier keys to press","type":"array","items":{"type":"string","enum":["Alt","Control","ControlOrMeta","Meta","Shift"]}}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_close","description":"Close the page","parameters":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_console_messages","description":"Returns all console messages","parameters":{"type":"object","properties":{"level":{"default":"info","description":"Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\".","type":"string","enum":["error","warning","info","debug"]},"all":{"description":"Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false.","type":"boolean"},"filename":{"description":"File name to save the console messages to. Relative file names are resolved against the workspace root. If not provided, messages are returned as text.","type":"string"}},"required":["level"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_drag","description":"Perform drag and drop between two elements","parameters":{"type":"object","properties":{"startElement":{"description":"Human-readable source element description used to obtain the permission to interact with the element","type":"string"},"startTarget":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"endElement":{"description":"Human-readable target element description used to obtain the permission to interact with the element","type":"string"},"endTarget":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"}},"required":["startTarget","endTarget"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_drop","description":"Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of \"paths\" or \"data\" must be provided.","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"paths":{"description":"Absolute paths to files to drop onto the element.","type":"array","items":{"type":"string"}},"data":{"description":"Data to drop, as a map of MIME type to string value (e.g. {\"text/plain\": \"hello\", \"text/uri-list\": \"https://example.com\"}).","type":"object","propertyNames":{"type":"string"},"additionalProperties":{"type":"string"}}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_emulate_media","description":"Emulate CSS media features for the page, for example switch between the light and dark color scheme. Omitted parameters are left unchanged; null clears an override.","parameters":{"type":"object","properties":{"colorScheme":{"description":"Emulates the prefers-color-scheme media feature","anyOf":[{"type":"string","enum":["light","dark"]},{"type":"null"}]},"reducedMotion":{"description":"Emulates the prefers-reduced-motion media feature","anyOf":[{"type":"string","enum":["reduce","no-preference"]},{"type":"null"}]},"forcedColors":{"description":"Emulates the forced-colors media feature","anyOf":[{"type":"string","enum":["active","none"]},{"type":"null"}]},"contrast":{"description":"Emulates the prefers-contrast media feature","anyOf":[{"type":"string","enum":["more","no-preference"]},{"type":"null"}]},"media":{"description":"Changes the CSS media type of the page","anyOf":[{"type":"string","enum":["screen","print"]},{"type":"null"}]}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_evaluate","description":"Evaluate JavaScript expression on page or element","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"function":{"type":"string","description":"() => { /* code */ } or (element) => { /* code */ } when element is provided"},"filename":{"description":"File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text.","type":"string"}},"required":["function"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_file_upload","description":"Upload one or multiple files","parameters":{"type":"object","properties":{"paths":{"description":"The absolute paths to the files to upload. Can be single file or multiple files. If omitted, file chooser is cancelled.","type":"array","items":{"type":"string"}}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_fill_form","description":"Fill multiple form fields","parameters":{"type":"object","properties":{"fields":{"type":"array","items":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"name":{"type":"string","description":"Human-readable field name"},"type":{"type":"string","enum":["textbox","checkbox","radio","combobox","slider"],"description":"Type of the field"},"value":{"type":"string","description":"Value to fill in the field. If the field is a checkbox, the value should be `true` or `false`. If the field is a combobox, the value should be the text of the option."}},"required":["target","name","type","value"],"additionalProperties":false},"description":"Fields to fill in"}},"required":["fields"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_find","description":"Search the accessibility snapshot of the current page for text or a regular expression. Returns matching snapshot nodes with a few lines of surrounding context (like search snippets), each shown under its path from the root of the tree, which is cheaper than capturing the whole snapshot when you only need to locate an element and its ref.","parameters":{"type":"object","properties":{"text":{"description":"Plain text to search for in the page snapshot (case-insensitive substring match). Provide either text or regex, not both.","type":"string"},"regex":{"description":"Regular expression to search for in the page snapshot. Matching is case-sensitive by default; wrap the pattern in slashes to add flags, e.g. \"/error/i\" for case-insensitive. Provide either text or regex, not both.","type":"string"},"filename":{"description":"Save results to a file instead of returning them in the response. Relative file names are resolved against the workspace root.","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_handle_dialog","description":"Handle a dialog","parameters":{"type":"object","properties":{"accept":{"type":"boolean","description":"Whether to accept the dialog."},"promptText":{"description":"The text of the prompt in case of a prompt dialog.","type":"string"}},"required":["accept"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_hover","description":"Hover over element on page","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"}},"required":["target"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_navigate","description":"Navigate to a URL","parameters":{"type":"object","properties":{"url":{"type":"string","description":"The URL to navigate to"}},"required":["url"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_navigate_back","description":"Go back to the previous page in the history","parameters":{"type":"object","properties":{},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_network_request","description":"Returns full details (headers and body) of a single network request, or a single part if `part` is set. Use the number from browser_network_requests.","parameters":{"type":"object","properties":{"index":{"type":"integer","minimum":1,"maximum":9007199254740991,"description":"1-based index of the request, as printed by browser_network_requests."},"part":{"description":"Return only this part of the request. Omit to return full details.","type":"string","enum":["request-headers","request-body","response-headers","response-body"]},"filename":{"description":"File name to save the result to. Relative file names are resolved against the workspace root. If not provided, output is returned as text.","type":"string"}},"required":["index"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_network_requests","description":"Returns a numbered list of network requests since loading the page. Use browser_network_request with the number to get full details.","parameters":{"type":"object","properties":{"static":{"default":false,"description":"Whether to include successful static resources like images, fonts, scripts, etc. Defaults to false.","type":"boolean"},"filter":{"description":"Only return requests whose URL matches this regexp (e.g. \"/api/.*user\").","type":"string"},"filename":{"description":"File name to save the network requests to. Relative file names are resolved against the workspace root. If not provided, requests are returned as text.","type":"string"}},"required":["static"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_press_key","description":"Press a key on the keyboard","parameters":{"type":"object","properties":{"key":{"type":"string","description":"Name of the key to press or a character to generate, such as `ArrowLeft` or `a`"}},"required":["key"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_resize","description":"Resize the browser window","parameters":{"type":"object","properties":{"width":{"type":"number","description":"Width of the browser window"},"height":{"type":"number","description":"Height of the browser window"}},"required":["width","height"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_run_code_unsafe","description":"Run a Playwright code snippet. Unsafe: executes arbitrary JavaScript in the Playwright server process and is RCE-equivalent.","parameters":{"type":"object","properties":{"code":{"description":"A JavaScript function containing Playwright code to execute. It will be invoked with a single argument, page, which you can use for any page interaction. For example: `async (page) => { await page.getByRole('button', { name: 'Submit' }).click(); return await page.title(); }`","type":"string"},"filename":{"description":"Load code from the specified file. Relative file names are resolved against the workspace root. If both code and filename are provided, code will be ignored.","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_select_option","description":"Select an option in a dropdown","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"values":{"type":"array","items":{"type":"string"},"description":"Array of values to select in the dropdown. This can be a single value or multiple values."}},"required":["target","values"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_snapshot","description":"Capture accessibility snapshot of the current page, this is better than screenshot","parameters":{"type":"object","properties":{"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"filename":{"description":"Save snapshot to a file instead of returning it in the response. Relative file names are resolved against the workspace root.","type":"string"},"depth":{"description":"Limit the depth of the snapshot tree","type":"number"},"boxes":{"description":"Include each element's bounding box as [box=x,y,width,height] in the snapshot. Coordinates are viewport-relative, in CSS pixels (Element.getBoundingClientRect)","type":"boolean"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_tabs","description":"List, create, close, or select a browser tab.","parameters":{"type":"object","properties":{"action":{"type":"string","enum":["list","new","close","select"],"description":"Operation to perform"},"index":{"description":"Tab index, used for close/select. If omitted for close, current tab is closed.","type":"number"},"url":{"description":"URL to navigate to in the new tab, used for new.","type":"string"}},"required":["action"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_take_screenshot","description":"Take a screenshot of the current page. You can't perform actions based on the screenshot, use browser_snapshot for actions.","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"description":"Exact target element reference from the page snapshot, or a unique element selector","type":"string"},"type":{"description":"Image format for the screenshot. If unset, inferred from the filename extension, otherwise png.","type":"string","enum":["png","jpeg","webp"]},"filename":{"description":"File name to save the screenshot to. Relative file names are resolved against the workspace root. If not specified, the screenshot is saved into the output directory as `page-{timestamp}.{png|jpeg|webp}`.","type":"string"},"fullPage":{"description":"When true, takes a screenshot of the full scrollable page, instead of the currently visible viewport. Cannot be used with element screenshots.","type":"boolean"},"scale":{"default":"css","description":"Image resolution scale. \"css\" produces a screenshot sized in CSS pixels (smaller, consistent across devices). \"device\" produces a high-resolution screenshot using device pixels (larger, accounts for the device pixel ratio). Default is css.","type":"string","enum":["css","device"]}},"required":["scale"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_type","description":"Type text into editable element","parameters":{"type":"object","properties":{"element":{"description":"Human-readable element description used to obtain permission to interact with the element","type":"string"},"target":{"type":"string","description":"Exact target element reference from the page snapshot, or a unique element selector"},"text":{"type":"string","description":"Text to type into the element"},"submit":{"description":"Whether to submit entered text (press Enter after)","type":"boolean"},"slowly":{"description":"Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once.","type":"boolean"}},"required":["target","text"],"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"playwright-mcp_browser_wait_for","description":"Wait for text to appear or disappear or a specified time to pass","parameters":{"type":"object","properties":{"time":{"description":"The time to wait in seconds, at most 30","type":"number"},"text":{"description":"The text to wait for","type":"string"},"textGone":{"description":"The text to wait for to disappear","type":"string"}},"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false}}},
  {"type":"function","function":{"name":"read","description":"Read a file or directory from the local filesystem. If the path does not exist, an error is returned.\n\nUsage:\n- The filePath parameter should be an absolute path.\n- By default, this tool returns up to 2000 lines from the start of the file.\n- The offset parameter is the line number to start from (1-indexed).\n- To read later sections, call this tool again with a larger offset.\n- Use the grep tool to find specific content in large files or files with long lines.\n- If you are unsure of the correct file path, use the glob tool to look up filenames by glob pattern.\n- Contents are returned with each line prefixed by its line number as `<line>: <content>`. For example, if a file has contents \"foo\\n\", you will receive \"1: foo\\n\". For directories, entries are returned one per line (without line numbers) with a trailing `/` for subdirectories.\n- Any line longer than 2000 characters is truncated.\n- Call this tool in parallel when you know there are multiple files you want to read.\n- Avoid tiny repeated slices (30 line chunks). If you need more context, read a larger window.\n- This tool can read image files and PDFs and return them as file attachments.\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"filePath":{"type":"string","description":"The absolute path to the file or directory to read"},"offset":{"minimum":0,"type":"integer","maximum":9007199254740991,"description":"The line number to start reading from (1-indexed)"},"limit":{"minimum":0,"type":"integer","maximum":9007199254740991,"description":"The maximum number of lines to read (defaults to 2000)"}},"required":["filePath"]}}},
  {"type":"function","function":{"name":"read_mcp_resource","description":"Read a specific resource from an MCP server using the server name and resource URI. The URI is an MCP identifier and does not need to be a file URL.","parameters":{"type":"object","properties":{"server":{"type":"string","description":"MCP server name exactly as returned by list_mcp_resources."},"uri":{"type":"string","description":"Resource URI to read. Use the exact URI string returned by list_mcp_resources."}},"required":["server","uri"],"additionalProperties":false}}},
  {"type":"function","function":{"name":"skill","description":"Load a specialized skill when the task at hand matches one of the skills listed in the system prompt.\n\nUse this tool to inject the skill's instructions and resources into current conversation. The output may contain detailed workflow guidance as well as references to scripts, files, etc in the same directory as the skill.\n\nThe skill name must match one of the skills listed in your system prompt.\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"name":{"type":"string","description":"The name of the skill from available_skills"}},"required":["name"]}}},
  {"type":"function","function":{"name":"task","description":"Launch a new agent to handle complex, multistep tasks autonomously.\n\nWhen using the Task tool, you must specify a subagent_type parameter to select which agent type to use.\n\nWhen NOT to use the Task tool:\n- If you want to read a specific file path, use the Read or Glob tool instead of the Task tool, to find the match more quickly\n- If you are searching for a specific class definition like \"class Foo\", use the Grep tool instead, to find the match more quickly\n- If you are searching for code within a specific file or set of 2-3 files, use the Read tool instead of the Task tool, to find the match more quickly\n- If no available agent is a good fit for the task, use other tools directly\n\n\nUsage notes:\n1. Launch multiple agents concurrently whenever possible, to maximize performance; to do that, use a single message with multiple tool uses\n2. Once you have delegated work to an agent, do not duplicate that work yourself. Continue with non-overlapping tasks, or wait for the result. For background tasks, you will be notified automatically when the result is ready.\n3. When the agent is done, it will return a single message back to you. The result returned by the agent is not visible to the user. To show the user the result, you should send a text message back to the user with a concise summary of the result. The output includes a task_id you can reuse later to continue the same subagent session.\n4. Each agent invocation starts with a fresh context unless you provide task_id to resume the same subagent session (which continues with its previous messages and tool outputs). When starting fresh, your prompt should contain a highly detailed task description for the agent to perform autonomously and you should specify exactly what information the agent should return back to you in its final and only message to you.\n5. The agent's outputs should generally be trusted\n6. Clearly tell the agent whether you expect it to write code or just to do research (search, file reads, web fetches, etc.), since it is not aware of the user's intent. Tell it how to verify its work if possible (e.g., relevant test commands).\n7. If the agent description mentions that it should be used proactively, then you should try your best to use it without the user having to ask for it first. Use your judgement.\n\nAvailable agent types and the tools they have access to:\n- explore: Fast agent specialized for exploring codebases. Use this when you need to quickly find files by patterns (eg. \"src/components/**/*.tsx\"), search code for keywords (eg. \"API endpoints\"), or answer questions about the codebase (eg. \"how do API endpoints work?\"). When calling this agent, specify the desired thoroughness level: \"quick\" for basic searches, \"medium\" for moderate exploration, or \"very thorough\" for comprehensive analysis across multiple locations and naming conventions.\n- general: General-purpose agent for researching complex questions and executing multi-step tasks. Use this agent to execute multiple units of work in parallel.","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"description":{"type":"string","description":"A short (3-5 words) description of the task"},"prompt":{"type":"string","description":"The task for the agent to perform"},"subagent_type":{"type":"string","description":"The type of specialized agent to use for this task"},"task_id":{"type":"string","description":"This should only be set if you mean to resume a previous task (you can pass a prior task_id and the task will continue the same subagent session as before instead of creating a fresh one)"},"command":{"type":"string","description":"The command that triggered this task"}},"required":["description","prompt","subagent_type"]}}},
  {"type":"function","function":{"name":"todowrite","description":"Create and maintain a structured task list for the current coding session. Tracks progress, organizes multi-step work, and surfaces status to the user.\n\n## When to use\nUse proactively when:\n- The task requires 3+ distinct steps or actions (not just 3 tool calls for a single conceptual step)\n- The work is non-trivial and benefits from planning\n- The user provides multiple tasks (numbered or comma-separated) or explicitly asks for a todo list\n- New instructions arrive - capture them as todos\n- You start a task - mark it `in_progress` (only one at a time) before working\n- You finish a task - mark it `completed` and add any follow-ups discovered during the work\n\n## When NOT to use\nSkip when:\n- The work is a single, straightforward task (or <3 trivial steps)\n- The request is purely informational or conversational\n- Tracking adds no organizational value\n\n## States\n- `pending` - not started\n- `in_progress` - actively working (exactly ONE at a time)\n- `completed` - finished successfully\n- `cancelled` - no longer needed\n\n## Rules\n- Update status in real time; don't batch completions\n- Mark `completed` only after the required work is actually done, including any required verification. Never based on intent.\n- Keep exactly one `in_progress` while work remains\n- If blocked or partial, keep it `in_progress` and add a follow-up todo describing the blocker\n- Preserve user-provided commands verbatim (flags, args, order)\n- Items should be specific and actionable; break large work into smaller steps\n\n## Examples\n\nUse it:\n- \"Add a dark mode toggle and run the tests\" -> multi-step feature + explicit verification\n- \"Rename getCwd -> getCurrentWorkingDirectory across the repo\" -> grep reveals 15 occurrences in 8 files\n- \"Implement registration, catalog, cart, checkout\" -> multiple complex features\n\nSkip it:\n- \"How do I print Hello World in Python?\" -> informational\n- \"Add a comment to calculateTotal\" -> single edit\n- \"Run npm install and tell me what happened\" -> one command\n\nWhen in doubt, use it.\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"todos":{"type":"array","items":{"type":"object","properties":{"content":{"type":"string","description":"Brief description of the task"},"status":{"type":"string","description":"Current status of the task: pending, in_progress, completed, cancelled"},"priority":{"type":"string","description":"Priority level of the task: high, medium, low"}},"required":["content","status","priority"]},"description":"The updated todo list"}},"required":["todos"]}}},
  {"type":"function","function":{"name":"webfetch","description":"- Fetches content from a specified URL\n- Takes a URL and optional format as input\n- Fetches the URL content, converts to requested format (markdown by default)\n- Returns the content in the specified format\n- Use this tool when you need to retrieve and analyze web content\n\nUsage notes:\n  - IMPORTANT: if another tool is present that offers better web fetching capabilities, is more targeted to the task, or has fewer restrictions, prefer using that tool instead of this one.\n  - The URL must be a fully-formed valid URL\n  - HTTP URLs will be automatically upgraded to HTTPS\n  - Format options: \"markdown\" (default), \"text\", or \"html\"\n  - This tool is read-only and does not modify any files\n  - Results may be summarized if the content is very large\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"url":{"type":"string","description":"The URL to fetch content from"},"format":{"type":"string","enum":["text","markdown","html"],"description":"The format to return the content in (text, markdown, or html). Defaults to markdown.","default":"markdown"},"timeout":{"type":"number","description":"Optional timeout in seconds (max 120)"}},"required":["url"]}}},
  {"type":"function","function":{"name":"websearch","description":"- Search the web using the session's web search provider - performs real-time web searches and can scrape content from specific URLs\n- Provides up-to-date information for current events and recent data\n- Supports configurable result counts and returns the content from the most relevant websites\n- Use this tool for accessing information beyond knowledge cutoff\n- Searches are performed automatically within a single API call\n\nUsage notes:\n  - Supports live crawling modes when available: 'fallback' (backup if cached unavailable) or 'preferred' (prioritize live crawling)\n  - Search types when available: 'auto' (balanced), 'fast' (quick results), 'deep' (comprehensive search)\n  - Configurable context length for optimal LLM integration\n  - Domain filtering and advanced search options available\n\nThe current year is 2026. You MUST use this year when searching for recent information or current events\n- Example: If the current year is 2026 and the user asks for \"latest AI news\", search for \"AI news 2026\", NOT \"AI news 2025\"\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"query":{"type":"string","description":"Websearch query"},"numResults":{"type":"number","description":"Number of search results to return (default: 8)"},"livecrawl":{"type":"string","enum":["fallback","preferred"],"description":"Live crawl mode - 'fallback': use live crawling as backup if cached content unavailable, 'preferred': prioritize live crawling (default: 'fallback')"},"type":{"type":"string","enum":["auto","fast","deep"],"description":"Search type - 'auto': balanced search (default), 'fast': quick results, 'deep': comprehensive search"},"contextMaxCharacters":{"type":"number","description":"Maximum characters for context string optimized for LLMs (default: 10000)"}},"required":["query"]}}},
  {"type":"function","function":{"name":"write","description":"Writes a file to the local filesystem.\n\nUsage:\n- This tool will overwrite the existing file if there is one at the provided path.\n- If this is an existing file, you MUST use the Read tool first to read the file's contents. This tool will fail if you did not read the file first.\n- ALWAYS prefer editing existing files in the codebase. NEVER write new files unless explicitly required.\n- NEVER proactively create documentation files (*.md) or README files. Only create documentation files if explicitly requested by the User.\n- Only use emojis if the user explicitly requests it. Avoid writing emojis to files unless asked.\n","parameters":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"content":{"type":"string","description":"The content to write to the file"},"filePath":{"type":"string","description":"The absolute path to the file to write (must be absolute, not relative)"}},"required":["content","filePath"]}}}
